/// <summary>
/// Handler on TOCPageConversionIntraclassActivated actvated
/// </summary>
/// <param name = "sender">control</param>
/// <param name = "e">event args</param>
[FormControlEventHandler(formControlStr(UnitOfMeasureConversion, TOCPageConversionIntraclass), FormControlEventType::PageActivated),
     SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void TOCPageConversionIntraclass_OnPageActivated(FormControl sender, FormControlEventArgs e)
{
    sender.formRun().dataSource(formDataSourceStr(UnitOfMeasureConversion, UnitOfMeasureConversionIntraclass)).active();
}

