}

/// <summary>
/// Handler on TOCPageConversionStandard actvated
/// </summary>
/// <param name = "sender">control</param>
/// <param name = "e">event args</param>
[FormControlEventHandler(formControlStr(UnitOfMeasureConversion, TOCPageConversionStandard), FormControlEventType::PageActivated),
     SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void TOCPageConversionStandard_OnPageActivated(FormControl sender, FormControlEventArgs e)
{
    FormRun fromRun = sender.formRun();
    fromRun.refreshUnitOfMeasureConversionDataSource(0);
}
